class Dog:
    def __init__(self, name):
        self.name = name              # self.name is an instance attribute

    def speak(self, times):
        return (self.name + " ") * times

d = Dog("Rex")
print(d.speak(2))                     # normal call
print(Dog.speak(d, 2))                # what Python really runs: self passed by hand
bound = d.speak                       # a bound method remembers d
print(bound.__self__ is d, bound(1))
try:
    class Bad:
        def hello():                  # forgot self
            return "hi"
    Bad().hello()
except TypeError as e:
    print("TypeError:", e)

class Upper(str):
    def __new__(cls, text):
        print("__new__ creates the object")
        return super().__new__(cls, text.upper())   # value fixed at creation

    def __init__(self, text):
        print("__init__ initialises it, text arg was", repr(text))

u = Upper("hello")
print(u, type(u).__name__, isinstance(u, str))

class Single:
    _inst = None
    def __new__(cls):
        if cls._inst is None:         # singleton: reuse one object
            cls._inst = super().__new__(cls)
        return cls._inst

print(Single() is Single())

