class Date:
    def __init__(self, y, m, d):
        self.y, self.m, self.d = y, m, d

    @classmethod
    def from_string(cls, s):          # alternate constructor
        y, m, d = map(int, s.split("-"))
        return cls(y, m, d)           # cls, so subclasses get themselves

    @staticmethod
    def is_valid(s):                  # plain helper, no self or cls
        return len(s.split("-")) == 3

    def __str__(self):
        return f"{self.y:04d}-{self.m:02d}-{self.d:02d}"

class MyDate(Date):
    pass

x = MyDate.from_string("2024-3-9")
print(type(x).__name__, x)
print(Date.is_valid("2024-3-9"), Date.is_valid("hello"))

import io
from typing import Protocol

class Readable(Protocol):             # structural type: anything with read()
    def read(self) -> str: ...

def shout(src: Readable) -> str:
    return src.read().upper()

class FakeFile:                       # no base class needed
    def read(self): return "fake data"

print(shout(io.StringIO("from stringio")))
print(shout(FakeFile()))
try:
    shout(42)                         # runtime failure, found only when called
except AttributeError as e:
    print("AttributeError:", e)

