class PetrolEngine:
    def start(self): return "vroom"
class FakeEngine:
    def start(self): return "fake start"

class Car:
    def __init__(self, engine):       # has-a: engine is injected
        self.engine = engine
    def drive(self):
        return "Car says " + self.engine.start()

print(Car(PetrolEngine()).drive())
print(Car(FakeEngine()).drive())      # swap part, e.g. in a test
c = Car(PetrolEngine())
c.engine = FakeEngine()               # even at runtime
