class Rect:
    def __init__(self, w, h): self.w, self.h = w, h
class Square(Rect):
    def __init__(self, s): super().__init__(s, s)
    def set_w(self, w): self.w = self.h = w
r = Square(2); r.set_w(5)
print("Square breaks Rect expectation:", r.w, r.h)

class Account:
    def __init__(self, balance):
        self.__balance = balance      # mangled to _Account__balance

    @property
    def balance(self):
        return self.__balance

    def withdraw(self, amount):
        if amount <= 0 or amount > self.__balance:   # keep invariant
            raise ValueError("bad amount")
        self.__balance -= amount

a = Account(100)
a.withdraw(30)
print(a.balance)
try:
    print(a.__balance)
except AttributeError as e:
    print("AttributeError:", e)
print(a._Account__balance)            # still reachable: not security
try:
    a.balance = 5                     # read-only property
except AttributeError as e:
    print("AttributeError:", e)
print(sorted(k for k in vars(a)))

class MinStack:
    def __init__(self):
        self.items = []
        self.mins = []                # mins[-1] is the true minimum

    def push(self, v):
        self.items.append(v)
        if not self.mins or v <= self.mins[-1]:   # <= handles duplicates
            self.mins.append(v)

    def pop(self):
        v = self.items.pop()
        if v == self.mins[-1]:
            self.mins.pop()
        return v

    def top(self): return self.items[-1]
    def get_min(self): return self.mins[-1]

s = MinStack()
for v in [5, 3, 7, 3, 1]:
    s.push(v)
    print("push", v, "min", s.get_min())
for _ in range(3):
    print("pop", s.pop(), "min", s.get_min())   # all O(1)

class P:
