    print("RuntimeError:", e)

from abc import ABC, abstractmethod
from typing import Protocol, runtime_checkable

class Shape(ABC):
    @abstractmethod
    def area(self): ...
    def describe(self):               # shared behaviour
        return f"{type(self).__name__} area {self.area()}"

class Sq(Shape):
    def area(self): return 4

try:
    Shape()
except TypeError as e:
    print("TypeError:", e)
print(Sq().describe())

@runtime_checkable
class HasArea(Protocol):
    def area(self): ...

class Duck:                           # no inheritance at all
    def area(self): return 1
print(isinstance(Duck(), HasArea), isinstance(Duck(), Shape))
Shape.register(Duck)                  # virtual subclass
print(isinstance(Duck(), Shape))
